import sys
from collections import defaultdict
import heapq

def solve():
    # Read input
    line = sys.stdin.readline().strip()
    if not line:
        return
    N, M = map(int, line.split())

    edges = []
    graph = defaultdict(list)

    for _ in range(M):
        u, v, w = map(int, sys.stdin.readline().split())
        edges.append((u, v, w))
        graph[u].append((v, w))

    # Since N <= 20, we can use dynamic programming with bitmasks
    # dp[mask][last] = minimum cost to visit all vertices in mask, ending at last vertex
    INF = float('inf')
    dp = {}

    # Initialize: start from each vertex
    for i in range(1, N + 1):
        dp[(1 << (i - 1), i)] = 0

    # Iterate over all masks
    for mask in range(1, 1 << N):
        for last in range(1, N + 1):
            if not (mask & (1 << (last - 1))):
                continue
            if (mask, last) not in dp:
                continue

            current_cost = dp[(mask, last)]

            # Try to extend the walk by going to any unvisited vertex
            for next_vertex in range(1, N + 1):
                if mask & (1 << (next_vertex - 1)):
                    continue  # already visited

                # Check if there's an edge from last to next_vertex
                for neighbor, weight in graph[last]:
                    if neighbor == next_vertex:
                        new_mask = mask | (1 << (next_vertex - 1))
                        new_cost = current_cost + weight

                        if (new_mask, next_vertex) not in dp or dp[(new_mask, next_vertex)] > new_cost:
                            dp[(new_mask, next_vertex)] = new_cost

    # Find the minimum cost to visit all vertices
    full_mask = (1 << N) - 1
    min_cost = INF

    for i in range(1, N + 1):
        if (full_mask, i) in dp:
            min_cost = min(min_cost, dp[(full_mask, i)])

    if min_cost == INF:
        print("No")
    else:
        print(min_cost)

solve()
