def minimumDistance(points):
    n = len(points)
    min_max_distance = float('inf')

    # Helper function to compute Manhattan distance
    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Try removing each point one by one
    for i in range(n):
        max_distance = 0
        # Compute the maximum Manhattan distance among remaining points
        for j in range(n):
            if j == i:
                continue
            for k in range(n):
                if k == i or k == j:
                    continue
                max_distance = max(max_distance, manhattan(points[j], points[k]))

        min_max_distance = min(min_max_distance, max_distance)

    return min_max_distance
