import sys
from collections import defaultdict

def read_input():
    grid = []
    for _ in range(3):
        row = list(map(int, input().split()))
        grid.append(row)
    return grid

def check_winner(board):
    # Check rows
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != 0:
            return board[i][0]

    # Check columns
    for j in range(3):
        if board[0][j] == board[1][j] == board[2][j] != 0:
            return board[0][j]

    # Check diagonals
    if board[0][0] == board[1][1] == board[2][2] != 0:
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] != 0:
        return board[0][2]

    return 0

def is_board_full(board):
    for i in range(3):
        for j in range(3):
            if board[i][j] == 0:
                return False
    return True

def get_empty_cells(board):
    empty = []
    for i in range(3):
        for j in range(3):
            if board[i][j] == 0:
                empty.append((i, j))
    return empty

def minimax(board, is_takahashi_turn, alpha, beta):
    # Check if someone won
    winner = check_winner(board)
    if winner == 1:  # Takahashi wins
        return 1
    elif winner == -1:  # Aoki wins
        return -1
    elif is_board_full(board):  # Game ended in draw
        # Count scores
        takahashi_score = sum(sum(row) for row in board if row[0] == 1 or row[1] == 1 or row[2] == 1)
        aoki_score = sum(sum(row) for row in board if row[0] == -1 or row[1] == -1 or row[2] == -1)
        if takahashi_score > aoki_score:
            return 1
        elif aoki_score > takahashi_score:
            return -1
        else:
            return 0

    empty_cells = get_empty_cells(board)

    if is_takahashi_turn:
        max_eval = float('-inf')
        for i, j in empty_cells:
            board[i][j] = 1  # Takahashi's move
            eval = minimax(board, False, alpha, beta)
            board[i][j] = 0  # Undo move

            max_eval = max(max_eval, eval)
            alpha = max(alpha, eval)

            if beta <= alpha:
                break  # Alpha-beta pruning
        return max_eval
    else:
        min_eval = float('inf')
        for i, j in empty_cells:
            board[i][j] = -1  # Aoki's move
            eval = minimax(board, True, alpha, beta)
            board[i][j] = 0  # Undo move

            min_eval = min(min_eval, eval)
            beta = min(beta, eval)

            if beta <= alpha:
                break  # Alpha-beta pruning
        return min_eval

def solve(grid):
    # Create a copy of the grid to work with
    board = [row[:] for row in grid]

    # In our implementation, we'll use a different approach:
    # We simulate the game by considering that when a player makes a move,
    # they place their marker (1 for Takahashi, -1 for Aoki) but don't 
    # immediately check for wins

    # Actually, let me reconsider. The key insight is that the game state
    # needs to track who placed what and when, and we need to check for wins
    # after each move.

    # Simpler approach: we'll simulate the full minimax
    def simulate_game(current_board, turn):
        # Check for win condition
        winner = check_winner(current_board)
        if winner == 1:
            return 1  # Takahashi wins
        elif winner == -1:
            return -1  # Aoki wins
        elif is_board_full(current_board):
            # Count final scores
            takahashi_score = 0
            aoki_score = 0
            for i in range(3):
                for j in range(3):
                    if current_board[i][j] == 1:
                        takahashi_score += grid[i][j]
                    elif current_board[i][j] == -1:
                        aoki_score += grid[i][j]
            if takahashi_score > aoki_score:
                return 1
            elif aoki_score > takahashi_score:
                return -1
            else:
                return 0  # Draw

        # Get available moves
        empty_cells = get_empty_cells(current_board)

        if turn == 1:  # Takahashi's turn
            best_value = float('-inf')
            for i, j in empty_cells:
                current_board[i][j] = 1
                value = simulate_game(current_board, -1)
                current_board[i][j] = 0

                best_value = max(best_value, value)
                if best_value == 1:
                    return 1  # Early termination - Takahashi can win
            return best_value
        else:  # Aoki's turn
            best_value = float('inf')
            for i, j in empty_cells:
                current_board[i][j] = -1
                value = simulate_game(current_board, 1)
                current_board[i][j] = 0

                best_value = min(best_value, value)
                if best_value == -1:
                    return -1  # Early termination - Aoki can win
            return best_value

    # Start simulation
    result = simulate_game([[0]*3 for _ in range(3)], 1)

    if result == 1:
        return "Takahashi"
    else:
        return "Aoki"

def main():
    grid = read_input()

    # We'll use a more efficient minimax approach
    def game_result(board_state, is_takahashi_turn):
        # Check if game ended due to win
        winner = check_winner(board_state)
        if winner == 1:
            return 1
        elif winner == -1:
            return -1

        # Check if board is full
        if is_board_full(board_state):
            # Calculate final scores
            takahashi_total = 0
            aoki_total = 0
            for i in range(3):
                for j in range(3):
                    if board_state[i][j] == 1:
                        takahashi_total += grid[i][j]
                    elif board_state[i][j] == -1:
                        aoki_total += grid[i][j]
            if takahashi_total > aoki_total:
                return 1
            elif aoki_total > takahashi_total:
                return -1
            else:
                return 0  # Tie

        # Continue game
        empty_cells = get_empty_cells(board_state)

        if is_takahashi_turn:
            best = float('-inf')
            for i, j in empty_cells:
                board_state[i][j] = 1
                result = game_result(board_state, False)
                board_state[i][j] = 0

