def stringIndices(wordsContainer, wordsQuery):
    def getSuffixes(word):
        suffixes = set()
        for i in range(len(word)):
            suffixes.add(word[i:])
        return suffixes

    # Create a map from suffix to list of (length, original_index) for wordsContainer
    suffix_map = {}

    for i, word in enumerate(wordsContainer):
        suffixes = getSuffixes(word)
        for suffix in suffixes:
            if suffix not in suffix_map:
                suffix_map[suffix] = []
            suffix_map[suffix].append((len(word), i))

    result = []

    for query in wordsQuery:
        best_length = float('inf')
        best_index = 0
        max_suffix_len = 0

        # Check all possible suffixes of the query
        for i in range(len(query), 0, -1):
            suffix = query[len(query)-i:]
            if suffix in suffix_map:
                # For this suffix, check all matching words
                for length, index in suffix_map[suffix]:
                    # Update if we found a better match
                    if (i > max_suffix_len or 
                        (i == max_suffix_len and length < best_length) or
                        (i == max_suffix_len and length == best_length and index < best_index)):
                        max_suffix_len = i
                        best_length = length
                        best_index = index

        # If no suffix found, use empty string suffix
        if max_suffix_len == 0:
            # Find the shortest word in wordsContainer
            min_length = float('inf')
            min_index = 0
            for i, word in enumerate(wordsContainer):
                if len(word) < min_length:
                    min_length = len(word)
                    min_index = i
            result.append(min_index)
        else:
            result.append(best_index)

    return result
