def can_transform(s1: str, s2: str) -> bool:
    """
    Return True if s1 can be transformed into s2 using swaps of indices (0,2) and (1,3) any number of times.
    """
    # The two allowed swaps only affect the pairs (0,2) and (1,3).
    # For each pair we can either keep the order or swap the two characters.
    # Therefore s2 must contain the same multiset of characters in each pair as s1.
    return (
        {s1[0], s1[2]} == {s2[0], s2[2]} and
        {s1[1], s1[3]} == {s2[1], s2[3]}
    )
