def minimumString(a, b, c):
    def merge(s1, s2):
        # If s2 is already a substring of s1
        if s2 in s1:
            return s1
        # Try to overlap s1 and s2
        for i in range(min(len(s1), len(s2)), 0, -1):
            if s1.endswith(s2[:i]):
                return s1 + s2[i:]
        return s1 + s2

    def mergeThree(s1, s2, s3):
        # Try all possible orders of merging
        orders = [
            [s1, s2, s3],
            [s1, s3, s2],
            [s2, s1, s3],
            [s2, s3, s1],
            [s3, s1, s2],
            [s3, s2, s1]
        ]

        result = None
        for order in orders:
            merged = merge(merge(order[0], order[1]), order[2])
            if result is None or len(merged) < len(result) or (len(merged) == len(result) and merged < result):
                result = merged
        return result

    return mergeThree(a, b, c)
