def longest_common_prefix_length(arr1, arr2):
    """
    Return the length of the longest common prefix between any pair (x, y)
    where x belongs to arr1 and y belongs to arr2.
    """
    # Helper: build a trie for all numbers in arr1
    trie = {}
    for num in arr1:
        node = trie
        s = str(num)
        for ch in s:
            node = node.setdefault(ch, {})
        # Mark the end of a number (not strictly needed for this problem)
        node.setdefault(None, True)

    max_len = 0
    for num in arr2:
        node = trie
        depth = 0
        s = str(num)
        for ch in s:
            if ch in node:
                node = node[ch]
                depth += 1
                if depth > max_len:
                    max_len = depth
            else:
                break
    return max_len
