def isFascinating(n):
    # Concatenate n, 2*n, and 3*n
    concatenated = str(n) + str(2 * n) + str(3 * n)

    # Check if the concatenated string has exactly 9 digits
    if len(concatenated) != 9:
        return False

    # Check if it contains all digits from 1 to 9 exactly once
    digit_count = {}
    for digit in concatenated:
        if digit == '0':
            return False
        if digit in digit_count:
            return False
        digit_count[digit] = 1

    # Check if we have all digits from 1 to 9
    if len(digit_count) != 9:
        return False

    # Verify that all digits 1-9 are present
    for i in range(1, 10):
        if str(i) not in digit_count:
            return False

    return True
