def occurrencesOfElement(nums, queries, x):
    # First pass: collect all indices where x occurs
    indices = []
    for i in range(len(nums)):
        if nums[i] == x:
            indices.append(i)

    # For each query, return the appropriate index or -1
    answer = []
    for query in queries:
        if query <= len(indices):
            answer.append(indices[query - 1])  # query is 1-indexed
        else:
            answer.append(-1)

    return answer
