def countMatchingSubarrays(nums: list[int], pattern: list[int]) -> int:
    """Return the number of subarrays of nums that match the given pattern."""
    n, m = len(nums), len(pattern)
    if m >= n:
        return 0

    count = 0
    # For each possible starting index of a subarray of length m+1
    for start in range(n - m):
        matched = True
        for k in range(m):
            a, b = nums[start + k], nums[start + k + 1]
            if pattern[k] == 1 and not (b > a):
                matched = False
                break
            if pattern[k] == 0 and not (b == a):
                matched = False
                break
            if pattern[k] == -1 and not (b < a):
                matched = False
                break
        if matched:
            count += 1
    return count
