        return True

    max_val = max(nums)

    # Smallest prime factor sieve up to max_val
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:            # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Union‑Find helpers
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    # Map each prime to the first index that contains it
    prime_to_index = {}

    for idx, val in enumerate(nums):
        x = val
        primes = set()
        while x > 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        for p in primes:
            if p in prime_to_index:
                union(idx, prime_to_index[p])
            else:
                prime_to_index[p] = idx

    # Check if all indices belong to the same component
    root0 = find(0)
    for i in range(1, n):
        if find(i) != root0:
            return False
    return True
```

